    func removeSubfolders(_ folder: [String]) -> [String] {
        var res = [String]()
        let folderSet = Set(folder)

        for f in folder {
            res.append(f)
            let chars = Array(f)
            for i in 0..<chars.count {
                if chars[i] == "/" && folderSet.contains(String(chars[0..<i])) {
                    res.removeLast()
