impl Solution {
    pub fn remove_subfolders(folder: Vec<String>) -> Vec<String> {
        let folder_set: HashSet<&str> = folder.iter().map(|s| s.as_str()).collect();
        let mut res = Vec::new();

        for f in &folder {
            let mut is_sub = false;
            for (i, c) in f.chars().enumerate() {
                if c == '/' && folder_set.contains(&f[..i]) {
                    is_sub = true;
                    break;
                }
            }
            if !is_sub {
                res.push(f.clone());
            }
        }
        res
    }
}
