    cur := t
    folders := strings.Split(path, "/")
    for i := 0; i < len(folders)-1; i++ {
        if folders[i] == "" {
            continue
        }
        cur = cur.children[folders[i]]
        if cur.endOfFolder {
            return true
        }
    }
    return false
